<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Carbon;

/**
 * `cash` table of the MyAT database.
 * Generated by `php artisan app:generate-models`; add relationships below.
 *
 * @property int|null $ID
 * @property Carbon|null $DT
 * @property float|null $ERB
 * @property float|null $PrepaidERB
 * @property float|null $PrepaidAlpha
 * @property float|null $Viva
 * @property float|null $Cash
 * @property float|null $Paypal
 * @property float|null $Ziraat
 * @property float|null $BoxGR
 * @property float|null $Box_Out
 * @property float|null $LittleBox
 * @property float|null $Total
 */
class Cash extends Model
{
    protected $table = 'cash';

    protected $primaryKey = 'ID';

    public $incrementing = true;

    protected $keyType = 'int';

    public $timestamps = false;

    protected $guarded = [];

    protected function casts(): array
    {
        return [
            'ID' => 'integer',
            'DT' => 'date',
            'ERB' => 'float',
            'PrepaidERB' => 'float',
            'PrepaidAlpha' => 'float',
            'Viva' => 'float',
            'Cash' => 'float',
            'Paypal' => 'float',
            'Ziraat' => 'float',
            'BoxGR' => 'float',
            'Box_Out' => 'float',
            'LittleBox' => 'float',
            'Total' => 'float',
        ];
    }

    /** Columns MariaDB calculates itself (GENERATED ALWAYS); never written from PHP. */
    public const GENERATED = ['Total'];

    /** The cash boxes, in PHPRunner's order, with their labels. */
    public const BOXES = [
        'ERB' => 'ERB', 'PrepaidERB' => 'Prepaid ERB', 'PrepaidAlpha' => 'Prepaid Alpha', 'Viva' => 'Viva', 'Cash' => 'Cash',
        'Paypal' => 'Paypal', 'Ziraat' => 'Ziraat', 'BoxGR' => 'Κουτί Ελλάδα', 'Box_Out' => 'Κουτί εκτός', 'LittleBox' => 'Κασελάκια',
    ];

    protected static function booted(): void
    {
        static::saving(function (Cash $cash): void {
            foreach (self::GENERATED as $column) {
                unset($cash->{$column});
            }
            // The boxes are NOT NULL DEFAULT 0.
            foreach (array_keys(self::BOXES) as $column) {
                $cash->{$column} = (float) ($cash->{$column} ?? 0);
            }
        });
    }
}
